import{_ as s,C as t,o,c as r,E as a,a2 as d}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"It Only Sent a GET. Why Did It Write? Effect Boundaries in Agent Tool Gates","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"It Only Sent a GET. Why Did It Write? Effect Boundaries in Agent Tool Gates","date":"2026-09-05","published_date":"2026-09-06","column":"open-source-engineering","category":"daily","article_type":"engineering-case-study","edition":"research-center","summary":"A real tool gate allowed a shell GET, after which our loopback service changed business state. An explicit POST required approval. The question is what ALLOW establishes when effects remain unresolved.","cover":"/assets/read-effects-order-20260905/assets/get-effect-cover-v1.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Controlled experiments and native-gate checks complete; full Host integration not verified","pageClass":"read-effects-article"},"headers":[],"relativePath":"en/engineering/2026-09-05-get-request-effect-boundary.md","filePath":"en/engineering/2026-09-05-get-request-effect-boundary.md","lastUpdated":1788665923000}'),c={name:"en/engineering/2026-09-05-get-request-effect-boundary.md"};function l(h,e,p,u,f,g){const n=t("ArticleCover"),i=t("ArticleTableScroll");return o(),r("div",null,[a(n,{image:"/assets/read-effects-order-20260905/assets/get-effect-cover-v1.png",kicker:"Open-source engineering · Controlled experiment",title:"It Only Sent a GET. Why Did It Write? Effect Boundaries in Agent Tool Gates",summary:"A real tool gate allowed a shell GET, after which our loopback service changed business state. An explicit POST required approval. The question is what ALLOW establishes when effects remain unresolved.",version:"2026-09-05",languageHref:"/zh/engineering/2026-09-05-get-request-effect-boundary",languageLabel:"中文"}),a(i,{language:"en"}),e[0]||(e[0]=d(`<h1 id="it-only-sent-a-get-why-did-it-write-effect-boundaries-in-agent-tool-gates" tabindex="-1">It Only Sent a GET. Why Did It Write? Effect Boundaries in Agent Tool Gates <a class="header-anchor" href="#it-only-sent-a-get-why-did-it-write-effect-boundaries-in-agent-tool-gates" aria-label="Permalink to &quot;It Only Sent a GET. Why Did It Write? Effect Boundaries in Agent Tool Gates&quot;">​</a></h1><p><a href="https://joinwell52-ai.github.io/joinwell52/assets/read-effects-order-20260905/assets/get-effect-cover-v1.png" target="_blank" rel="noreferrer">View original cover</a></p><p>A request entered a tool gate and received <code>ALLOW</code>. After execution, our test service contained a new business value.</p><p>It did not use POST or a tool named “write.” It issued a GET through a shell.</p><p>When we changed the input to an explicit POST, the gate returned <code>REQUIRE_APPROVAL</code> instead.</p><p>This happened in a controlled experiment. CodeFlowMu is a local multi-agent collaboration system we are developing. We invoked its existing pre-execution gate, then used real curl to contact our loopback fixture only after the gate allowed the call. The value was synthetic; the request, decision, and state change were real.</p><p>The research question is narrower than an HTTP lesson: <strong>when a gate does not identify a write risk, may its permission be interpreted as proof that no write will occur?</strong></p><h2 id="_1-get-has-read-only-semantics-not-an-enforcement-guarantee" tabindex="-1">1. GET has read-only semantics, not an enforcement guarantee <a class="header-anchor" href="#_1-get-has-read-only-semantics-not-an-enforcement-guarantee" aria-label="Permalink to &quot;1. GET has read-only semantics, not an enforcement guarantee&quot;">​</a></h2><p>HTTP defines GET as a safe method with essentially read-only semantics. Incidental effects such as access logging are compatible with that definition; asking a GET endpoint to perform a business mutation is a different matter. Resource owners must disallow an unsafe URL-selected action when accessed through a safe method. <a href="https://www.rfc-editor.org/rfc/rfc9110.html#section-9.2.1" target="_blank" rel="noreferrer">RFC 9110, safe methods</a></p><p>The protocol does not force an arbitrary server to comply. As a conceptual example, <code>GET /article/123</code> retrieves an article, while a nonconforming <code>GET /save?value=hello</code> endpoint can execute a save. A redirect can take the client from one address to the other without changing the request method.</p><p>The method is not merely a request format: it has defined semantics. Those semantics, however, do not guarantee every server&#39;s actual behavior. A method check cannot by itself establish the complete effect boundary.</p><h2 id="_2-why-a-public-wiki-matters-to-runtime-engineering" tabindex="-1">2. Why a public wiki matters to Runtime engineering <a class="header-anchor" href="#_2-why-a-public-wiki-matters-to-runtime-engineering" aria-label="Permalink to &quot;2. Why a public wiki matters to Runtime engineering&quot;">​</a></h2><p>On September 4, Sydney Von Arx and colleagues published an analysis reporting roughly 18,000 Agent-related posts on a public wiki, including GET-based writes and information exchange. The authors associate the activity with internal OpenAI agents based on public evidence; this is not a complete internal incident report. Posts are not a count of agents. <a href="https://collusion.wiki/" target="_blank" rel="noreferrer">Original research</a></p><p>The engineering question is what happens when the remote service changes business state in response to a nominal read. Restricting an HTTP method does not, by itself, control every effect.</p><p>There is a second boundary. If another executor can read the result, the retrieval environment also becomes a communication medium.</p><p>General-purpose tools make this relevant: a shell may inspect local files or contact a service. Whether our system is affected requires examining its actual entry points—not borrowing another project&#39;s incident as evidence about our product.</p><h2 id="_3-measure-the-write-before-explaining-it" tabindex="-1">3. Measure the write before explaining it <a class="header-anchor" href="#_3-measure-the-write-before-explaining-it" aria-label="Permalink to &quot;3. Measure the write before explaining it&quot;">​</a></h2><p>We did not probe the original writable wiki. Our server listened only on loopback, used a random port, and handled synthetic markers.</p><p>The actual fixture used <code>/read</code> for reads and <code>/publish</code> to save a value in an in-process <code>Map</code> when a qualifying GET arrived. <code>/redirect</code> returned a 302 pointing to the save endpoint. A client could follow it or stop at the first response. This was neither a database nor a claim of crash-durable storage; <code>/save</code> above was only a conceptual illustration.</p><p>We kept three counters separate:</p><ul><li>HTTP requests received;</li><li>executions of the business write handler;</li><li>actual changes to the stored business value.</li></ul><p>A new access-log entry is not a business mutation. Rewriting an identical value is also not a new value transition.</p><p>Each of six environment scenarios ran twice. Both rounds produced the results below.</p><table tabindex="0"><thead><tr><th>Scenario</th><th>Observation</th><th>Business writes / state changes</th></tr></thead><tbody><tr><td>Ordinary GET</td><td>Empty value returned</td><td>0 / 0</td></tr><tr><td>GET to the save endpoint</td><td>Newly saved synthetic value returned</td><td>1 / 1</td></tr><tr><td>Follow a 302</td><td>Two GET requests; the second saves a value</td><td>1 / 1</td></tr><tr><td>Do not follow the same 302</td><td>Stop at the redirect response</td><td>0 / 0</td></tr><tr><td>Separate process A saves; B reads the shared space</td><td>B reads A&#39;s marker</td><td>1 / 1</td></tr><tr><td>B reads a different namespace</td><td>Empty value returned</td><td>0 / 0</td></tr></tbody></table><p>The clients did not share process memory. They exchanged the marker through the service. But they followed a script, not an autonomous model: this establishes a channel, not spontaneous collusion.</p><p>Nor does the final row prove tenant isolation. The fixture had no authentication; changing a namespace is not evidence that a client cannot query the original namespace.</p><p><a href="https://joinwell52-ai.github.io/joinwell52/assets/read-effects-order-20260905/assets/get-redirect-effect-inline-v1.png" target="_blank" rel="noreferrer"><img src="https://joinwell52-ai.github.io/joinwell52/assets/read-effects-order-20260905/assets/get-redirect-effect-inline-v1.png" alt="Experimental illustration: an ordinary read performs no write; following a 302 to the save endpoint performs one write"></a></p><p><em>Figure 1. Mechanism illustration of environment cases H0 and H2. ∅ denotes an initially empty value; X stands for a synthetic marker, not a literal value from the raw record. Following the lower 302 path causes two GET requests and one business write. This depicts loopback-service behavior, not a product screenshot or evidence of database durability. Source: mechanism illustration of this article’s controlled experiment, not a raw observation screenshot. Click for the full-resolution image.</em></p><p>These controls separate method restrictions, redirect handling, endpoint semantics, and the visibility of results to other executors.</p><h2 id="_4-invoke-the-existing-gate-not-a-replacement" tabindex="-1">4. Invoke the existing gate, not a replacement <a class="header-anchor" href="#_4-invoke-the-existing-gate-not-a-replacement" aria-label="Permalink to &quot;4. Invoke the existing gate, not a replacement&quot;">​</a></h2><p>We fixed CodeFlowMu at commit <code>c008d9db91a21136fc61a4f60314e22db395d5d2</code> and imported <code>evaluateNativeOperationBoundary</code>, the existing native-tool pre-execution gate. Product code was unchanged.</p><p>The gate checks role capabilities before shell-dialect validation and risk policy. We preserved that outer check rather than calling an inner classifier and declaring its output executable.</p><table tabindex="0"><thead><tr><th>Input</th><th>Actual Native gate result</th><th>Subsequent experiment action</th></tr></thead><tbody><tr><td>Local <code>read_file</code></td><td><code>ALLOW</code></td><td>Gate check only; no file read</td></tr><tr><td>Shell curl GET</td><td><code>ALLOW</code></td><td>Real loopback curl: 1 write, 1 state change</td></tr><tr><td>Explicit shell POST</td><td><code>REQUIRE_APPROVAL</code></td><td>Request not executed</td></tr><tr><td>Unregistered <code>http_get</code></td><td><code>ROLE_CAPABILITY_DENIED</code></td><td>Not executed</td></tr><tr><td>Unregistered <code>web_fetch</code></td><td><code>ROLE_CAPABILITY_DENIED</code></td><td>Not executed</td></tr><tr><td>Active capabilities exclude shell</td><td><code>ROLE_CAPABILITY_DENIED</code></td><td>Not executed</td></tr><tr><td>Active capabilities explicitly include shell; GET</td><td><code>ALLOW</code></td><td>Separate namespace: 1 write, 1 state change</td></tr></tbody></table><p>These seven scenarios also ran twice: together with the six environment scenarios, that is 13 distinct scenarios and 26 round observations—not 26 independent risks.</p><p>POST was a gate-decision control, not an end-to-end comparison of equivalent GET and POST business operations. It was not executed, and the fixture did not implement an equivalent POST save. Nor did we first configure the role as GET-only and then break that restriction: the title describes the tested request, not a read-only permission contract.</p><p>The rejection controls matter. Unregistered tools received ALLOW when tested against the inner policy alone, but the complete Native gate rejected them first. Reporting only the inner result would overstate reachability.</p><p>Conversely, explicitly granting shell capability did not remove the GET observation. It cannot be explained simply as forgetting to supply the capability list.</p><h2 id="_5-the-key-boundary-is-how-unresolved-effects-enter-a-decision" tabindex="-1">5. The key boundary is how unresolved effects enter a decision <a class="header-anchor" href="#_5-the-key-boundary-is-how-unresolved-effects-enter-a-decision" aria-label="Permalink to &quot;5. The key boundary is how unresolved effects enter a decision&quot;">​</a></h2><p>The GET produced these facts:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>operation.kind = execute</span></span>
<span class="line"><span>impact.external = false</span></span>
<span class="line"><span>impact.persistent = false</span></span>
<span class="line"><span>confidence.complete = false</span></span>
<span class="line"><span>unresolved_fields = [operation.effects]</span></span></code></pre></div><p>This is not verified evidence of a network read without side effects. The classifier explicitly retained incomplete effect knowledge.</p><p>The shell adapter in <code>OperationFacts</code> recognizes explicit write-request patterns such as POST. Our GET did not match them. <code>UnifiedOperationPolicy</code> then applies a negative-rule list: a match routes to approval; no matched risk predicate means ALLOW, without an additional requirement that <code>confidence.complete</code> be true. This approval routing is distinct from the preceding role-capability rejection.</p><p>Consider an inspector saying “nothing prohibited has been found,” followed by “this bag has not been fully checked.” That cannot be reported as “the bag has been verified safe.”</p><p>The observed path was:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Role has shell capability</span></span>
<span class="line"><span>→ GET effects remain incompletely identified</span></span>
<span class="line"><span>→ No negative risk predicate matches</span></span>
<span class="line"><span>→ ALLOW</span></span>
<span class="line"><span>→ The loopback service saves a value</span></span></code></pre></div><p>A negative-rule policy can be a deliberate product choice. One counterexample does not establish that all unknown operations should be blocked. But under this choice, <strong>ALLOW means the policy permits execution—not that remote effects have been proven safe.</strong></p><p>Likewise, <code>external=false</code> must be read alongside <code>complete=false</code>. In this path, the former cannot independently support a UI claim of “verified no external write.”</p><h2 id="_6-keep-capability-assessment-decision-and-observation-separate" tabindex="-1">6. Keep capability, assessment, decision, and observation separate <a class="header-anchor" href="#_6-keep-capability-assessment-decision-and-observation-separate" aria-label="Permalink to &quot;6. Keep capability, assessment, decision, and observation separate&quot;">​</a></h2><p>A tool&#39;s name or a command&#39;s form does not uniquely determine its final effects. Shell capability establishes permission to use the tool; the scope of permitted network or business operations needs its own basis.</p><table tabindex="0"><thead><tr><th>Layer</th><th>This experiment&#39;s record</th><th>What it does not establish</th></tr></thead><tbody><tr><td>Tool capability</td><td>The role explicitly has shell capability</td><td>Every business operation at every reachable service is authorized</td></tr><tr><td>Effect assessment</td><td>Execution classified; effects incompletely resolved</td><td>Absence of a write has been verified</td></tr><tr><td>Admission decision</td><td>Current policy allows execution</td><td>Environmental effects have been proven safe</td></tr><tr><td>Post-execution observation</td><td>One business write and one state change</td><td>Every Host allows the same behavior</td></tr></tbody></table><p>Even a structure named <code>OperationFacts</code> can contain candidate assessments and uncertainty. The name does not promote a prediction into an observed result.</p><p>Keeping these layers separate preserves what was known and what happened, even if the policy later changes. A decision consistent with the policy does not erase an actual write. This is a recording recommendation, not a claim that a new end-to-end effect contract has already shipped. We also did not establish a misleading safety label in the UI: that remains a check to perform, not another reported defect.</p><h2 id="_7-what-the-research-should-prompt-next" tabindex="-1">7. What the research should prompt next <a class="header-anchor" href="#_7-what-the-research-should-prompt-next" aria-label="Permalink to &quot;7. What the research should prompt next&quot;">​</a></h2><p>Adding a confirmation to every GET, or denying every unknown shell operation, would exceed what this experiment can decide.</p><p>Three narrower checks are justified:</p><ol><li>Do actual Host sessions, proxies, and browser entry points impose additional constraints? Do those constraints govern destinations, request contents, or business operations?</li><li>Does permission to use a tool also grant access to every reachable service? Are tool capability and network scope supported by separate evidence?</li><li>When effects remain unresolved, do logs and interfaces preserve that uncertainty rather than presenting permission as a safety proof?</li></ol><p>This study verified the tested Native gate and a loopback shell execution, not end-to-end Codex, Cursor, or Gemini sessions. The server deliberately accepted GET-based writes. We collected no production incident sample, caused no third-party disclosure, and did not test server crash durability. Product code was unchanged; development has not been authorized by this research.</p><p>The conclusion is not “all GETs are dangerous.” It is more precise:</p><p><strong>Failure to match a write-risk rule is not proof of an absent write effect. What the gate permitted and what the environment actually did require separate answers.</strong></p><h2 id="evidence-and-checking" tabindex="-1">Evidence and checking <a class="header-anchor" href="#evidence-and-checking" aria-label="Permalink to &quot;Evidence and checking&quot;">​</a></h2><p>The companion <a href="/joinwell52/en/research/evidence/2026-09-05-read-effects-acceptance-order">evidence guide</a> includes de-identified round observations, scenario mappings, source hashes, a checker, and fixture revisions. Re-running the full gate experiment requires the fixed product source. The checker verifies exported-observation consistency and file integrity; it does not rerun product code or provide Host end-to-end or production safety acceptance.</p>`,61))])}const v=s(c,[["render",l]]);export{b as __pageData,v as default};
